//! Core hopscotch-hashing table.
//!
//! This is a from-scratch implementation of hopscotch hashing (Herlihy, Shavit,
//! Tzafrir) using only `std`, mirroring the layout of the C++ header pair
//! `tsl/hopscotch_hash.h` + `tsl/hopscotch_map.h`: the table lives here and
//! [`crate::tsl::hopscotch_map`] is a thin typed facade over it.
//!
//! How it works: every bucket owns a *neighborhood* of the
//! [`NEIGHBORHOOD_SIZE`] buckets starting at itself. A bucket keeps a bitmap
//! (`infos`) describing which slots of its neighborhood currently hold one of
//! its entries, so a lookup only ever touches the set bits of a single bitmap.
//! On insert, the first empty slot at or after the home bucket is found and
//! then "hopped" backwards — repeatedly swapping it with an entry that can
//! legally move forward — until it lands inside the home neighborhood. If no
//! sequence of hops succeeds, the entry goes to an overflow list and the home
//! bucket's overflow bit is set; too many overflow entries trigger a rehash.

use std::borrow::Borrow;
use std::hash::{BuildHasher, Hash};

/// Number of buckets in a bucket's neighborhood; matches the default
/// `NeighborhoodSize` template argument of `tsl::hopscotch_map`.
pub const NEIGHBORHOOD_SIZE: usize = 62;

/// Bit of `Bucket::infos` flagging "some of my entries are in the overflow list".
const OVERFLOW_BIT: u64 = 1 << NEIGHBORHOOD_SIZE;
/// Bits of `Bucket::infos` describing the neighborhood occupancy.
const NEIGHBORHOOD_MASK: u64 = OVERFLOW_BIT - 1;

/// Smallest allocated bucket count (a power of two, like the C++ default
/// power-of-two growth policy).
pub const MIN_BUCKET_COUNT: usize = 8;

/// Default `max_load_factor()` of the container.
pub const DEFAULT_MAX_LOAD_FACTOR: f32 = 0.95;

/// One slot of the bucket array.
struct Bucket<K, V> {
    infos: u64,
    entry: Option<(K, V)>,
}

impl<K, V> Bucket<K, V> {
    const fn empty() -> Self {
        Bucket {
            infos: 0,
            entry: None,
        }
    }

    fn is_empty(&self) -> bool {
        self.entry.is_none()
    }
}

impl<K: Clone, V: Clone> Clone for Bucket<K, V> {
    fn clone(&self) -> Self {
        Bucket {
            infos: self.infos,
            entry: self.entry.clone(),
        }
    }
}

/// Where an entry physically lives.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Loc {
    /// Index into the bucket array.
    Bucket(usize),
    /// Index into the overflow list.
    Overflow(usize),
}

/// A hash table using hopscotch hashing with an overflow list.
pub struct HopscotchHash<K, V, S> {
    /// `bucket_count + NEIGHBORHOOD_SIZE - 1` slots when allocated, so that the
    /// neighborhood of the last addressable bucket never runs past the end.
    /// Empty (and `bucket_count == 0`) while the table is still unallocated.
    buckets: Vec<Bucket<K, V>>,
    /// Entries that no hop sequence could fit into their neighborhood.
    overflow: Vec<(K, V)>,
    /// Power of two; only the first `bucket_count` buckets are hash targets.
    bucket_count: usize,
    len: usize,
    max_load_factor: f32,
    load_threshold: usize,
    hash_builder: S,
}

impl<K, V, S> HopscotchHash<K, V, S> {
    /// Creates an empty table that allocates nothing until the first insert.
    pub fn with_hasher(hash_builder: S) -> Self {
        HopscotchHash {
            buckets: Vec::new(),
            overflow: Vec::new(),
            bucket_count: 0,
            len: 0,
            max_load_factor: DEFAULT_MAX_LOAD_FACTOR,
            load_threshold: 0,
            hash_builder,
        }
    }

    pub fn len(&self) -> usize {
        self.len
    }

    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn bucket_count(&self) -> usize {
        self.bucket_count
    }

    pub fn max_load_factor(&self) -> f32 {
        self.max_load_factor
    }

    pub fn load_factor(&self) -> f32 {
        if self.bucket_count == 0 {
            0.0
        } else {
            self.len as f32 / self.bucket_count as f32
        }
    }

    pub fn hasher(&self) -> &S {
        &self.hash_builder
    }

    pub fn clear(&mut self) {
        for bucket in &mut self.buckets {
            bucket.infos = 0;
            bucket.entry = None;
        }
        self.overflow.clear();
        self.len = 0;
    }

    pub fn iter(&self) -> Iter<'_, K, V> {
        Iter {
            buckets: self.buckets.iter(),
            overflow: self.overflow.iter(),
            remaining: self.len,
        }
    }

    pub fn iter_mut(&mut self) -> IterMut<'_, K, V> {
        IterMut {
            buckets: self.buckets.iter_mut(),
            overflow: self.overflow.iter_mut(),
            remaining: self.len,
        }
    }

    fn threshold_for(bucket_count: usize, max_load_factor: f32) -> usize {
        let threshold = (bucket_count as f32 * max_load_factor) as usize;
        threshold.max(1)
    }

    /// Overflow entries tolerated before the table grows instead.
    fn overflow_threshold(&self) -> usize {
        (self.bucket_count / 8).max(NEIGHBORHOOD_SIZE / 4)
    }
}

impl<K: Hash + Eq, V, S: BuildHasher> HopscotchHash<K, V, S> {
    /// Creates a table sized to hold `capacity` entries without rehashing.
    pub fn with_capacity_and_hasher(capacity: usize, hash_builder: S) -> Self {
        let mut table = Self::with_hasher(hash_builder);
        if capacity > 0 {
            table.reserve(capacity);
        }
        table
    }

    /// Sets the maximum load factor, growing the table if it is now overloaded.
    pub fn set_max_load_factor(&mut self, max_load_factor: f32) {
        self.max_load_factor = max_load_factor.clamp(0.05, 0.99);
        if self.bucket_count > 0 {
            self.load_threshold = Self::threshold_for(self.bucket_count, self.max_load_factor);
            if self.len > self.load_threshold {
                self.rehash(self.bucket_count * 2);
            }
        }
    }

    /// Grows the table so `count` entries fit under the max load factor.
    pub fn reserve(&mut self, count: usize) {
        let needed = (count as f32 / self.max_load_factor).ceil() as usize;
        if needed > self.bucket_count {
            self.rehash(needed);
        }
    }

    pub fn get<Q>(&self, key: &Q) -> Option<&V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let loc = self.locate(key)?;
        Some(self.value_at(loc))
    }

    pub fn get_mut<Q>(&mut self, key: &Q) -> Option<&mut V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let loc = self.locate(key)?;
        Some(self.value_at_mut(loc))
    }

    pub fn get_key_value<Q>(&self, key: &Q) -> Option<(&K, &V)>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let loc = self.locate(key)?;
        Some(self.entry_at(loc))
    }

    pub fn contains_key<Q>(&self, key: &Q) -> bool
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.locate(key).is_some()
    }

    /// C++ `insert` semantics: keeps the existing value when `key` is already
    /// present. Returns `true` when the entry was inserted.
    pub fn insert_no_overwrite(&mut self, key: K, value: V) -> bool {
        self.ensure_allocated();
        let ibucket = self.bucket_of(self.hash_of(&key));
        if self.find_in(ibucket, &key).is_some() {
            return false;
        }
        self.insert_new(ibucket, key, value);
        true
    }

    /// C++ `insert_or_assign` semantics: returns the replaced value, if any.
    pub fn insert_or_assign(&mut self, key: K, value: V) -> Option<V> {
        self.ensure_allocated();
        let ibucket = self.bucket_of(self.hash_of(&key));
        if let Some(loc) = self.find_in(ibucket, &key) {
            return Some(std::mem::replace(self.value_at_mut(loc), value));
        }
        self.insert_new(ibucket, key, value);
        None
    }

    /// C++ `operator[]` semantics: inserts `default()` when `key` is absent.
    pub fn get_or_insert_with<F: FnOnce() -> V>(&mut self, key: K, default: F) -> &mut V {
        self.ensure_allocated();
        let ibucket = self.bucket_of(self.hash_of(&key));
        if let Some(loc) = self.find_in(ibucket, &key) {
            return self.value_at_mut(loc);
        }
        let loc = self.insert_new(ibucket, key, default());
        self.value_at_mut(loc)
    }

    pub fn remove<Q>(&mut self, key: &Q) -> Option<V>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        self.remove_entry(key).map(|(_, value)| value)
    }

    pub fn remove_entry<Q>(&mut self, key: &Q) -> Option<(K, V)>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        if self.bucket_count == 0 {
            return None;
        }
        let ibucket = self.bucket_of(self.hash_of(key));
        let entry = match self.find_in(ibucket, key)? {
            Loc::Bucket(i) => {
                self.buckets[ibucket].infos &= !(1u64 << (i - ibucket));
                self.buckets[i].entry.take()?
            }
            Loc::Overflow(i) => {
                let entry = self.overflow.remove(i);
                if !self.overflow_belongs_to(ibucket) {
                    self.buckets[ibucket].infos &= !OVERFLOW_BIT;
                }
                entry
            }
        };
        self.len -= 1;
        Some(entry)
    }

    /// Inserts an entry known to be absent, growing the table first if needed.
    fn insert_new(&mut self, ibucket: usize, key: K, value: V) -> Loc {
        let mut ibucket = ibucket;
        if self.len + 1 > self.load_threshold {
            self.rehash(self.bucket_count * 2);
            ibucket = self.bucket_of(self.hash_of(&key));
        }
        let mut loc = self.place(ibucket, key, value);
        self.len += 1;
        if matches!(loc, Loc::Overflow(_)) && self.overflow.len() > self.overflow_threshold() {
            // Too much traffic in the overflow list: grow and re-place
            // everything, then find where this entry ended up.
            let hash = {
                let (key, _) = self.entry_at(loc);
                self.hash_of(key)
            };
            self.rehash(self.bucket_count * 2);
            let ibucket = self.bucket_of(hash);
            // Re-locating by hash alone is enough: `place` never loses entries.
            loc = self
                .find_hash_slot(ibucket, hash)
                .expect("re-placed entry must be findable");
        }
        loc
    }

    /// Stores `(key, value)` in `ibucket`'s neighborhood, hopping the nearest
    /// empty slot closer, or in the overflow list as a last resort.
    fn place(&mut self, ibucket: usize, key: K, value: V) -> Loc {
        if let Some(mut iempty) = self.find_empty_bucket(ibucket) {
            while iempty - ibucket >= NEIGHBORHOOD_SIZE {
                match self.swap_empty_bucket_closer(iempty) {
                    Some(icloser) => iempty = icloser,
                    None => break,
                }
            }
            if iempty - ibucket < NEIGHBORHOOD_SIZE {
                self.buckets[iempty].entry = Some((key, value));
                self.buckets[ibucket].infos |= 1u64 << (iempty - ibucket);
                return Loc::Bucket(iempty);
            }
        }
        self.buckets[ibucket].infos |= OVERFLOW_BIT;
        self.overflow.push((key, value));
        Loc::Overflow(self.overflow.len() - 1)
    }

    /// First empty slot at or after `ibucket`, if any.
    fn find_empty_bucket(&self, ibucket: usize) -> Option<usize> {
        self.buckets[ibucket..]
            .iter()
            .position(Bucket::is_empty)
            .map(|offset| ibucket + offset)
    }

    /// Moves one entry forward into the empty slot `iempty` so that the empty
    /// slot travels backwards. Returns the slot that became empty.
    fn swap_empty_bucket_closer(&mut self, iempty: usize) -> Option<usize> {
        let start = (iempty + 1).saturating_sub(NEIGHBORHOOD_SIZE);
        for ihome in start..iempty {
            let mut infos = self.buckets[ihome].infos & NEIGHBORHOOD_MASK;
            let mut bit = 0usize;
            while infos != 0 && ihome + bit < iempty {
                if infos & 1 != 0 {
                    // `iempty - ihome < NEIGHBORHOOD_SIZE` holds by choice of
                    // `start`, so `ihome` may legally own `iempty`.
                    let ifrom = ihome + bit;
                    self.buckets[iempty].entry = self.buckets[ifrom].entry.take();
                    let infos = &mut self.buckets[ihome].infos;
                    *infos &= !(1u64 << bit);
                    *infos |= 1u64 << (iempty - ihome);
                    return Some(ifrom);
                }
                infos >>= 1;
                bit += 1;
            }
        }
        None
    }

    /// Reallocates to (at least) `bucket_count` buckets and re-places every entry.
    fn rehash(&mut self, bucket_count: usize) {
        let bucket_count = bucket_count.next_power_of_two().max(MIN_BUCKET_COUNT);
        let mut buckets = Vec::with_capacity(bucket_count + NEIGHBORHOOD_SIZE - 1);
        buckets.resize_with(bucket_count + NEIGHBORHOOD_SIZE - 1, Bucket::empty);

        let old_buckets = std::mem::replace(&mut self.buckets, buckets);
        let old_overflow = std::mem::take(&mut self.overflow);
        self.bucket_count = bucket_count;
        self.load_threshold = Self::threshold_for(bucket_count, self.max_load_factor);

        let entries = old_buckets
            .into_iter()
            .filter_map(|bucket| bucket.entry)
            .chain(old_overflow);
        for (key, value) in entries {
            let ibucket = self.bucket_of(self.hash_of(&key));
            self.place(ibucket, key, value);
        }
    }

    fn ensure_allocated(&mut self) {
        if self.bucket_count == 0 {
            self.rehash(MIN_BUCKET_COUNT);
        }
    }

    fn hash_of<Q>(&self, key: &Q) -> u64
    where
        Q: Hash + ?Sized,
    {
        self.hash_builder.hash_one(key)
    }

    fn bucket_of(&self, hash: u64) -> usize {
        debug_assert!(self.bucket_count.is_power_of_two());
        (hash as usize) & (self.bucket_count - 1)
    }

    fn locate<Q>(&self, key: &Q) -> Option<Loc>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        if self.bucket_count == 0 {
            return None;
        }
        self.find_in(self.bucket_of(self.hash_of(key)), key)
    }

    /// Searches `ibucket`'s neighborhood, then the overflow list if flagged.
    fn find_in<Q>(&self, ibucket: usize, key: &Q) -> Option<Loc>
    where
        K: Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let infos = self.buckets[ibucket].infos;
        let mut neighborhood = infos & NEIGHBORHOOD_MASK;
        let mut bit = 0usize;
        while neighborhood != 0 {
            if neighborhood & 1 != 0 {
                let i = ibucket + bit;
                if let Some((k, _)) = &self.buckets[i].entry {
                    if k.borrow() == key {
                        return Some(Loc::Bucket(i));
                    }
                }
            }
            neighborhood >>= 1;
            bit += 1;
        }
        if infos & OVERFLOW_BIT != 0 {
            let i = self.overflow.iter().position(|(k, _)| k.borrow() == key)?;
            return Some(Loc::Overflow(i));
        }
        None
    }

    /// Finds the single entry of `ibucket` whose key hashes to `hash`; used to
    /// re-locate an entry after a rehash moved it.
    fn find_hash_slot(&self, ibucket: usize, hash: u64) -> Option<Loc> {
        let infos = self.buckets[ibucket].infos;
        let mut neighborhood = infos & NEIGHBORHOOD_MASK;
        let mut bit = 0usize;
        while neighborhood != 0 {
            if neighborhood & 1 != 0 {
                let i = ibucket + bit;
                if let Some((k, _)) = &self.buckets[i].entry {
                    if self.hash_of(k) == hash {
                        return Some(Loc::Bucket(i));
                    }
                }
            }
            neighborhood >>= 1;
            bit += 1;
        }
        if infos & OVERFLOW_BIT != 0 {
            let i = self
                .overflow
                .iter()
                .position(|(k, _)| self.hash_of(k) == hash)?;
            return Some(Loc::Overflow(i));
        }
        None
    }

    fn overflow_belongs_to(&self, ibucket: usize) -> bool {
        self.overflow
            .iter()
            .any(|(k, _)| self.bucket_of(self.hash_of(k)) == ibucket)
    }

    fn entry_at(&self, loc: Loc) -> (&K, &V) {
        let (key, value) = match loc {
            Loc::Bucket(i) => self.buckets[i].entry.as_ref().expect("occupied bucket"),
            Loc::Overflow(i) => &self.overflow[i],
        };
        (key, value)
    }

    fn value_at(&self, loc: Loc) -> &V {
        self.entry_at(loc).1
    }

    fn value_at_mut(&mut self, loc: Loc) -> &mut V {
        let (_, value) = match loc {
            Loc::Bucket(i) => self.buckets[i].entry.as_mut().expect("occupied bucket"),
            Loc::Overflow(i) => &mut self.overflow[i],
        };
        value
    }
}

impl<K: Clone, V: Clone, S: Clone> Clone for HopscotchHash<K, V, S> {
    fn clone(&self) -> Self {
        HopscotchHash {
            buckets: self.buckets.clone(),
            overflow: self.overflow.clone(),
            bucket_count: self.bucket_count,
            len: self.len,
            max_load_factor: self.max_load_factor,
            load_threshold: self.load_threshold,
            hash_builder: self.hash_builder.clone(),
        }
    }
}

/// Iterator over `(&K, &V)`, bucket array first then overflow list.
pub struct Iter<'a, K, V> {
    buckets: std::slice::Iter<'a, Bucket<K, V>>,
    overflow: std::slice::Iter<'a, (K, V)>,
    remaining: usize,
}

impl<'a, K, V> Iterator for Iter<'a, K, V> {
    type Item = (&'a K, &'a V);

    fn next(&mut self) -> Option<Self::Item> {
        for bucket in self.buckets.by_ref() {
            if let Some((key, value)) = &bucket.entry {
                self.remaining -= 1;
                return Some((key, value));
            }
        }
        let (key, value) = self.overflow.next()?;
        self.remaining -= 1;
        Some((key, value))
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<K, V> ExactSizeIterator for Iter<'_, K, V> {}

/// Iterator over `(&K, &mut V)`.
pub struct IterMut<'a, K, V> {
    buckets: std::slice::IterMut<'a, Bucket<K, V>>,
    overflow: std::slice::IterMut<'a, (K, V)>,
    remaining: usize,
}

impl<'a, K, V> Iterator for IterMut<'a, K, V> {
    type Item = (&'a K, &'a mut V);

    fn next(&mut self) -> Option<Self::Item> {
        for bucket in self.buckets.by_ref() {
            if let Some((key, value)) = &mut bucket.entry {
                self.remaining -= 1;
                return Some((key, value));
            }
        }
        let (key, value) = self.overflow.next()?;
        self.remaining -= 1;
        Some((key, value))
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<K, V> ExactSizeIterator for IterMut<'_, K, V> {}

/// Consuming iterator over `(K, V)`.
pub struct IntoIter<K, V> {
    buckets: std::vec::IntoIter<Bucket<K, V>>,
    overflow: std::vec::IntoIter<(K, V)>,
    remaining: usize,
}

impl<K, V> Iterator for IntoIter<K, V> {
    type Item = (K, V);

    fn next(&mut self) -> Option<Self::Item> {
        for bucket in self.buckets.by_ref() {
            if let Some(entry) = bucket.entry {
                self.remaining -= 1;
                return Some(entry);
            }
        }
        let entry = self.overflow.next()?;
        self.remaining -= 1;
        Some(entry)
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        (self.remaining, Some(self.remaining))
    }
}

impl<K, V> ExactSizeIterator for IntoIter<K, V> {}

impl<K, V, S> IntoIterator for HopscotchHash<K, V, S> {
    type Item = (K, V);
    type IntoIter = IntoIter<K, V>;

    fn into_iter(self) -> Self::IntoIter {
        IntoIter {
            remaining: self.len,
            buckets: self.buckets.into_iter(),
            overflow: self.overflow.into_iter(),
        }
    }
}

