//! `HopscotchMap` — the `tsl::hopscotch_map<K, V>` equivalent.
//!
//! A typed facade over [`crate::tsl::hopscotch_hash::HopscotchHash`], exposing
//! the C++ container's surface with the C++ semantics kept intact where they
//! differ from `std::collections::HashMap`:
//!
//! * [`HopscotchMap::insert`] takes a `(key, value)` pair and does **not**
//!   overwrite an existing key (like `std::unordered_map::insert`); use
//!   [`HopscotchMap::insert_or_assign`] for replacing semantics.
//! * `map[key] = value` (via [`IndexMut`]) inserts `V::default()` for a missing
//!   key, like the C++ `operator[]`. The immutable `map[key]` panics on a
//!   missing key, since it cannot insert.
//! * `==` compares sizes and then every key/value pair, independent of the
//!   internal layout, like `operator==` on the C++ container.

use std::borrow::Borrow;
use std::collections::hash_map::DefaultHasher;
use std::fmt;
use std::hash::{BuildHasher, BuildHasherDefault, Hash};
use std::ops::{Index, IndexMut};

use super::hopscotch_hash::{self, HopscotchHash};

/// Deterministic default hasher builder (`std`'s SipHash-1-3, unseeded).
pub type DefaultHashBuilder = BuildHasherDefault<DefaultHasher>;

/// A hash map implemented with hopscotch hashing.
pub struct HopscotchMap<K, V, S = DefaultHashBuilder> {
