//! `std::stoi` re-implemented on top of `std`.

/// Failure modes of [`stoi`], matching the exceptions `std::stoi` throws.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum StoiError {
    /// `std::invalid_argument`: no digits could be converted.
    Invalid,
    /// `std::out_of_range`: the value does not fit in an `int`.
    OutOfRange,
}

/// `std::stoi(str)` with the default base 10: skips leading whitespace, accepts
/// one optional sign, then converts the longest run of digits and ignores the
/// rest of the string (so `"12abc"` is `12` and `"0x10"` is `0`).
pub fn stoi(str: &str) -> Result<i32, StoiError> {
    let bytes = str.as_bytes();
    let mut i = 0;

    while i < bytes.len() && is_space(bytes[i]) {
        i += 1;
    }
    let negative = match bytes.get(i) {
        Some(b'-') => {
            i += 1;
            true
        }
        Some(b'+') => {
            i += 1;
            false
        }
        _ => false,
    };

    let first_digit = i;
    let mut value: i64 = 0;
    let mut overflowed = false;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let digit = i64::from(bytes[i] - b'0');
        match value.checked_mul(10).and_then(|v| v.checked_add(digit)) {
            Some(v) => value = v,
            // `strtol` keeps consuming digits and reports ERANGE.
            None => overflowed = true,
        }
        i += 1;
    }

    if i == first_digit {
        return Err(StoiError::Invalid);
    }
    if overflowed {
        return Err(StoiError::OutOfRange);
    }
    let value = if negative { -value } else { value };
    i32::try_from(value).map_err(|_| StoiError::OutOfRange)
}

/// `std::isspace` in the C locale.
fn is_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_like_stoi() {
        assert_eq!(stoi("0"), Ok(0));
        assert_eq!(stoi("14"), Ok(14));
        assert_eq!(stoi("-3"), Ok(-3));
        assert_eq!(stoi("+7"), Ok(7));
        assert_eq!(stoi(" \t 42"), Ok(42));
        assert_eq!(stoi("12abc"), Ok(12));
        assert_eq!(stoi("0x10"), Ok(0));
        assert_eq!(stoi("2147483647"), Ok(i32::MAX));
        assert_eq!(stoi("-2147483648"), Ok(i32::MIN));
    }

    #[test]
    fn rejects_like_stoi() {
        assert_eq!(stoi(""), Err(StoiError::Invalid));
        assert_eq!(stoi("abc"), Err(StoiError::Invalid));
        assert_eq!(stoi("-"), Err(StoiError::Invalid));
        assert_eq!(stoi("   "), Err(StoiError::Invalid));
        assert_eq!(stoi("2147483648"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("-2147483649"), Err(StoiError::OutOfRange));
        assert_eq!(stoi("99999999999999999999999"), Err(StoiError::OutOfRange));
    }
}

