//! Tests for the hopscotch table: C++-visible semantics plus a differential
//! check of the table itself against `std::collections::HashMap`.

use std::collections::HashMap;
use std::hash::{BuildHasher, Hasher};

use super::hopscotch_map::HopscotchMap;

/// Deterministic xorshift, so failures reproduce.
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
}

/// Hasher that maps everything to the same bucket, forcing the overflow list
/// and the "growing does not help" back-off path.
#[derive(Default, Clone)]
struct ConstantHashBuilder;

struct ConstantHasher;

impl Hasher for ConstantHasher {
    fn finish(&self) -> u64 {
        42
    }
    fn write(&mut self, _bytes: &[u8]) {}
}

impl BuildHasher for ConstantHashBuilder {
    type Hasher = ConstantHasher;
    fn build_hasher(&self) -> ConstantHasher {
        ConstantHasher
    }
}

#[test]
fn insert_does_not_overwrite() {
    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    assert!(map.insert((1, 10)));
    assert!(!map.insert((1, 20)));
    assert_eq!(map.get(&1), Some(&10));
    assert_eq!(map.len(), 1);

    assert_eq!(map.insert_or_assign(1, 20), Some(10));
    assert_eq!(map.get(&1), Some(&20));
    assert_eq!(map.len(), 1);
}

#[test]
fn index_mut_inserts_default() {
    let mut map: HopscotchMap<i32, i32> = HopscotchMap::new();
    assert!(map.is_empty());
    map[0] = 999;
    assert_eq!(map.len(), 1);
    assert_eq!(map[0], 999);

    map[0] += 1;
    assert_eq!(map[0], 1000);
    assert_eq!(map.len(), 1);
}

#[test]
fn equality_is_layout_independent() {
    let forward: HopscotchMap<i32, i32> = (0..200).map(|i| (i, i * 11)).collect();
    let backward: HopscotchMap<i32, i32> = (0..200).rev().map(|i| (i, i * 11)).collect();
    assert_eq!(forward, backward);

    let mut changed = backward.clone();
    changed.insert_or_assign(0, 999);
    assert_ne!(forward, changed);

    let mut shorter = forward.clone();
    shorter.remove(&199);
    assert_ne!(forward, shorter);
    assert_ne!(shorter, forward);
}

#[test]
fn matches_std_hashmap_under_mixed_operations() {
    let mut map: HopscotchMap<u64, u64> = HopscotchMap::new();
    let mut reference: HashMap<u64, u64> = HashMap::new();
    let mut rng = Rng(0x9E3779B97F4A7C15);

    for step in 0..40_000u64 {
        let key = rng.next() % 2_000;
        match step % 4 {
            0 | 1 => {
                let value = rng.next();
                assert_eq!(
                    map.insert((key, value)),
                    reference.insert(key, value).is_none() || {
                        reference.insert(key, value);
                        false
                    }
                );
            }
            2 => {
                let value = rng.next();
                assert_eq!(map.insert_or_assign(key, value), reference.insert(key, value));
            }
            _ => assert_eq!(map.remove(&key), reference.remove(&key)),
        }
        assert_eq!(map.len(), reference.len());
    }

    for (key, value) in &reference {
        assert_eq!(map.get(key), Some(value));
    }
    for (key, value) in &map {
        assert_eq!(reference.get(key), Some(value));
    }
    assert_eq!(map.iter().count(), reference.len());
    for key in 0..2_000 {
        assert_eq!(map.contains_key(&key), reference.contains_key(&key));
    }
}

#[test]
fn survives_a_degenerate_hash_function() {
    let mut map: HopscotchMap<u32, u32, ConstantHashBuilder> =
        HopscotchMap::with_hasher(ConstantHashBuilder);

    for i in 0..500 {
        assert!(map.insert((i, i * 3)));
    }
    assert_eq!(map.len(), 500);
    for i in 0..500 {
        assert_eq!(map.get(&i), Some(&(i * 3)));
    }
    for i in (0..500).step_by(3) {
        assert_eq!(map.remove(&i), Some(i * 3));
    }
    for i in 0..500 {
        let expected = (i % 3 != 0).then_some(i * 3);
        assert_eq!(map.get(&i).copied(), expected);
    }
}

#[test]
fn reserve_clear_and_string_keys() {
    let mut map: HopscotchMap<String, usize> = HopscotchMap::with_capacity(128);
    assert!(map.bucket_count() >= 128);

    for i in 0..500 {
        map.insert((format!("key{i}"), i));
    }
    // Borrowed lookups, like `find` on a `const char*`.
    assert_eq!(map.get("key499"), Some(&499));
    assert_eq!(map.get("missing"), None);
    assert_eq!(map.at("key0"), &0);

    map.clear();
    assert!(map.is_empty());
    assert_eq!(map.get("key0"), None);
    assert!(map.insert(("key0".to_string(), 7)));
    assert_eq!(map.len(), 1);
}

#[test]
fn respects_max_load_factor() {
    let mut map: HopscotchMap<u32, u32> = HopscotchMap::new();
    map.set_max_load_factor(0.5);
    for i in 0..1_000 {
        map.insert((i, i));
    }
    assert!(map.load_factor() <= 0.5, "load factor {}", map.load_factor());
    assert_eq!(map.len(), 1_000);
}

#[test]
fn into_iter_yields_every_entry() {
    let map: HopscotchMap<i32, i32> = (0..300).map(|i| (i, i * 11)).collect();
    let mut entries: Vec<(i32, i32)> = map.into_iter().collect();
    entries.sort_unstable();
    assert_eq!(entries, (0..300).map(|i| (i, i * 11)).collect::<Vec<_>>());
}

