#[test]
fn matches_std_hashmap_under_mixed_operations() {
    let mut map: HopscotchMap<u64, u64> = HopscotchMap::new();
    let mut reference: HashMap<u64, u64> = HashMap::new();
    let mut rng = Rng(0x9E3779B97F4A7C15);

    for step in 0..40_000u64 {
        let key = rng.next() % 2_000;
        match step % 4 {
            0 | 1 => {
                let value = rng.next();
                assert_eq!(
                    map.insert((key, value)),
                    reference.insert(key, value).is_none() || {
                        reference.insert(key, value);
                        false
                    }
                );
            }
            2 => {
                let value = rng.next();
                assert_eq!(map.insert_or_assign(key, value), reference.insert(key, value));
            }
            _ => assert_eq!(map.remove(&key), reference.remove(&key)),
        }
        assert_eq!(map.len(), reference.len());
    }

    for (key, value) in &reference {
        assert_eq!(map.get(key), Some(value));
    }
    for (key, value) in &map {
        assert_eq!(reference.get(key), Some(value));
    }
    assert_eq!(map.iter().count(), reference.len());
    for key in 0..2_000 {
        assert_eq!(map.contains_key(&key), reference.contains_key(&key));
    }
}

