//! Tests for the hopscotch table: C++-visible semantics plus a differential
//! check of the table itself against `std::collections::HashMap`.

use std::collections::HashMap;
use std::hash::{BuildHasher, Hasher};

use super::hopscotch_map::HopscotchMap;

/// Deterministic xorshift, so failures reproduce.
struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }
}

/// Hasher that maps everything to the same bucket, forcing the overflow list
/// and the "growing does not help" back-off path.
#[derive(Default, Clone)]
struct ConstantHashBuilder;

struct ConstantHasher;

impl Hasher for ConstantHasher {
    fn finish(&self) -> u64 {
        42
    }
    fn write(&mut self, _bytes: &[u8]) {}
}

impl BuildHasher for ConstantHashBuilder {
    type Hasher = ConstantHasher;
    fn build_hasher(&self) -> ConstantHasher {
        ConstantHasher
    }
}

